<x-app-layout><x-slot name="header"><x-page-header title="Rekap: {{ $questionnaire->title }}" description="Respons ditampilkan secara anonim."><x-slot name="actions"><a class="btn btn-outline-primary" href="{{ route('questionnaires.export', $questionnaire) }}">Unduh CSV</a></x-slot></x-page-header></x-slot><div class="row g-3 mb-4"><div class="col-md-6"><x-stat-card label="Total respons" :value="$report['totalResponses']" /></div><div class="col-md-6"><x-stat-card label="Progres target" :value="$report['progress'] === null ? 'Tidak ditetapkan' : $report['progress'].'%'" /></div></div>@foreach($report['questions'] as $item)<section class="card shadow-sm mb-3"><div class="card-body"><h2 class="h5">{{ $loop->iteration }}. {{ $item['question']->text }}</h2><p class="text-muted small">{{ $item['count'] }} jawaban</p>@if($item['question']->type === 'multiple_choice')<ul class="list-group list-group-flush">@foreach($item['options'] as $option)<li class="list-group-item d-flex justify-content-between">{{ $option['label'] }} <span>{{ $option['count'] }} ({{ $option['percent'] }}%)</span></li>@endforeach</ul>@elseif($item['question']->type === 'likert')<p>Rata-rata: {{ $item['average'] ?? '-' }}</p><div class="d-flex gap-3">@foreach($item['distribution'] as $point => $count)<span>{{ $point }}: {{ $count }}</span>@endforeach</div>@else<ul class="list-group list-group-flush">@foreach($item['texts']->take(20) as $text)<li class="list-group-item">{{ $text }}</li>@endforeach</ul>@endif</div></section>@endforeach</x-app-layout>
